import sqlite3

def siapkan(con):
    con.execute("PRAGMA foreign_keys = ON")
    con.executescript("""
    CREATE TABLE anggota (id INTEGER PRIMARY KEY, nama TEXT NOT NULL);
    CREATE TABLE buku (id INTEGER PRIMARY KEY, judul TEXT NOT NULL);
    CREATE TABLE pinjaman (
      id INTEGER PRIMARY KEY,
      anggota_id INTEGER NOT NULL REFERENCES anggota(id) ON DELETE RESTRICT,
      buku_id INTEGER NOT NULL REFERENCES buku(id) ON DELETE RESTRICT,
      kembali TEXT
    );
    CREATE UNIQUE INDEX satu_pinjaman_aktif ON pinjaman(buku_id) WHERE kembali IS NULL;
    """)

def pinjam(con, anggota_id, buku_id):
    con.execute("BEGIN IMMEDIATE")
    try:
        cur = con.execute("INSERT INTO pinjaman (anggota_id, buku_id) VALUES (?, ?)",
                          (anggota_id, buku_id))
        nomor = cur.lastrowid
        con.execute("COMMIT")
        return nomor
    except Exception:
        con.execute("ROLLBACK")
        raise

def kembalikan(con, nomor, tanggal):
    from datetime import date
    if not isinstance(tanggal, str) or date.fromisoformat(tanggal).isoformat() != tanggal:
        raise ValueError("Gunakan tanggal ISO YYYY-MM-DD")
    cur = con.execute("UPDATE pinjaman SET kembali = ? WHERE id = ? AND kembali IS NULL",
                      (tanggal, nomor))
    if cur.rowcount != 1:
        raise ValueError("Pinjaman tidak ditemukan atau sudah kembali")

def main():
    con = sqlite3.connect(":memory:", isolation_level=None)
    try:
        siapkan(con)
        con.execute("INSERT INTO anggota VALUES (?, ?)", (1, "Ana"))
        con.execute("INSERT INTO buku VALUES (?, ?)", (1, "Python"))
        nomor = pinjam(con, 1, 1)
        try:
            pinjam(con, 1, 1)
        except sqlite3.IntegrityError:
            print("Ditolak: buku masih dipinjam")
        print("Aktif:", con.execute("SELECT COUNT(*) FROM pinjaman WHERE kembali IS NULL").fetchone()[0])
        kembalikan(con, nomor, "2026-01-02")
        print("Aktif setelah kembali:", con.execute("SELECT COUNT(*) FROM pinjaman WHERE kembali IS NULL").fetchone()[0])
        print("Pinjaman baru:", pinjam(con, 1, 1))
    finally:
        con.close()

if __name__ == "__main__":
    main()

import sqlite3

def siapkan(con):
    con.execute("PRAGMA foreign_keys = ON")
    con.executescript("""
    CREATE TABLE teknisi (id INTEGER PRIMARY KEY, nama TEXT NOT NULL);
    CREATE TABLE tiket (
      id INTEGER PRIMARY KEY, judul TEXT NOT NULL,
      teknisi_id INTEGER REFERENCES teknisi(id) ON DELETE RESTRICT,
      status TEXT NOT NULL DEFAULT 'BARU'
        CHECK(status IN ('BARU', 'DIPROSES', 'SELESAI')),
      CHECK(status = 'BARU' OR teknisi_id IS NOT NULL)
    );
    CREATE TABLE riwayat (
      id INTEGER PRIMARY KEY,
      tiket_id INTEGER NOT NULL REFERENCES tiket(id) ON DELETE RESTRICT,
      status TEXT NOT NULL CHECK(status IN ('BARU', 'DIPROSES', 'SELESAI'))
    );
    """)

def buat(con, nomor, judul):
    if not isinstance(judul, str) or not judul.strip():
        raise ValueError("Judul wajib diisi")
    con.execute("BEGIN IMMEDIATE")
    try:
        con.execute("INSERT INTO tiket (id, judul) VALUES (?, ?)", (nomor, judul.strip()))
        con.execute("INSERT INTO riwayat (tiket_id, status) VALUES (?, 'BARU')", (nomor,))
        con.execute("COMMIT")
    except Exception:
        con.execute("ROLLBACK")
        raise

def ubah(con, nomor, status_baru, teknisi_id=None):
    con.execute("BEGIN IMMEDIATE")
    try:
        row = con.execute("SELECT status, teknisi_id FROM tiket WHERE id = ?", (nomor,)).fetchone()
        if row is None:
            raise ValueError("Tiket tidak ditemukan")
        status, petugas = row
        if status == 'BARU' and status_baru == 'DIPROSES' and teknisi_id is not None:
            petugas = teknisi_id
        elif status == 'DIPROSES' and status_baru == 'SELESAI' and teknisi_id is None:
            pass
        else:
            raise ValueError("Transisi tidak diizinkan")
        con.execute("UPDATE tiket SET status = ?, teknisi_id = ? WHERE id = ?",
                    (status_baru, petugas, nomor))
        con.execute("INSERT INTO riwayat (tiket_id, status) VALUES (?, ?)", (nomor, status_baru))
        con.execute("COMMIT")
    except Exception:
        con.execute("ROLLBACK")
        raise

def main():
    con = sqlite3.connect(":memory:", isolation_level=None)
    try:
        siapkan(con)
        con.execute("INSERT INTO teknisi VALUES (?, ?)", (1, "Ana"))
        buat(con, 101, "Link putus")
        try:
            ubah(con, 101, "SELESAI")
        except ValueError as error:
            print("Ditolak:", error)
        ubah(con, 101, "DIPROSES", 1)
        ubah(con, 101, "SELESAI")
        print(con.execute("SELECT t.id, n.nama, t.status FROM tiket t JOIN teknisi n ON n.id = t.teknisi_id ORDER BY t.id").fetchall())
        print([row[0] for row in con.execute("SELECT status FROM riwayat WHERE tiket_id = ? ORDER BY id", (101,))])
    finally:
        con.close()

if __name__ == "__main__":
    main()

